/* ===== SOURCE SNAPSHOT END ===== */

IF OBJECT_ID(N'tempdb..#ResolvedWorkflowNotificationGroups') IS NOT NULL
BEGIN
    DROP TABLE #ResolvedWorkflowNotificationGroups;
END;

;WITH TargetGroupNameMatches AS
(
    SELECT
        grp.Name,
        MIN(grp.ID) AS TargetGroupID,
        COUNT_BIG(1) AS MatchCount
    FROM SCore.Groups AS grp
    WHERE grp.RowStatus NOT IN (0,254)
    GROUP BY
        grp.Name
)
SELECT
    sourceNg.ID AS WorkflowStatusNotificationGroupID,
    sourceNg.Guid AS WorkflowStatusNotificationGroupGuid,
    sourceNg.WorkflowID,
    wf.Name AS WorkflowName,
    sourceNg.WorkflowStatusGuid,
    ws.Name AS WorkflowStatusName,
    sourceNg.SourceGroupID,
    sourceNg.SourceGroupGuid,
    sourceNg.SourceGroupName,
    CASE
        WHEN sourceNg.ID = -1 OR sourceNg.SourceGroupID = -1 THEN -1
        WHEN targetByGuid.ID IS NOT NULL THEN targetByGuid.ID
        WHEN targetByName.MatchCount = 1 THEN targetByName.TargetGroupID
        ELSE NULL
    END AS TargetGroupID,
    CASE
        WHEN sourceNg.ID = -1 OR sourceNg.SourceGroupID = -1 THEN N'Sentinel'
        WHEN targetByGuid.ID IS NOT NULL THEN N'Guid'
        WHEN targetByName.MatchCount = 1 THEN N'Name'
        WHEN targetByName.MatchCount > 1 THEN N'AmbiguousName'
        ELSE N'Unresolved'
    END AS GroupResolutionMethod,
    sourceNg.CanAction
INTO #ResolvedWorkflowNotificationGroups
FROM @SourceWorkflowStatusNotificationGroups AS sourceNg
LEFT JOIN @SourceWorkflow AS wf
    ON wf.ID = sourceNg.WorkflowID
LEFT JOIN @SourceWorkflowStatus AS ws
    ON ws.Guid = sourceNg.WorkflowStatusGuid
LEFT JOIN SCore.Groups AS targetByGuid
    ON targetByGuid.Guid = sourceNg.SourceGroupGuid
   AND targetByGuid.RowStatus NOT IN (0,254)
LEFT JOIN TargetGroupNameMatches AS targetByName
    ON targetByName.Name = sourceNg.SourceGroupName;

SELECT
    GroupResolutionMethod,
    COUNT_BIG(1) AS NotificationGroupRowCount
FROM #ResolvedWorkflowNotificationGroups
GROUP BY
    GroupResolutionMethod
ORDER BY
    GroupResolutionMethod;

SELECT
    SourceGroupID,
    SourceGroupGuid,
    SourceGroupName,
    GroupResolutionMethod,
    COUNT_BIG(1) AS AffectedNotificationGroupRows,
    STRING_AGG(CONVERT(nvarchar(max), WorkflowStatusNotificationGroupID), N', ') WITHIN GROUP (ORDER BY WorkflowStatusNotificationGroupID) AS NotificationGroupIDs
FROM #ResolvedWorkflowNotificationGroups
WHERE WorkflowStatusNotificationGroupID <> -1
  AND TargetGroupID IS NULL
GROUP BY
    SourceGroupID,
    SourceGroupGuid,
    SourceGroupName,
    GroupResolutionMethod
ORDER BY
    SourceGroupName,
    SourceGroupID;

SELECT
    WorkflowStatusNotificationGroupID,
    WorkflowStatusNotificationGroupGuid,
    WorkflowID,
    WorkflowName,
    WorkflowStatusGuid,
    WorkflowStatusName,
    SourceGroupID,
    SourceGroupGuid,
    SourceGroupName,
    GroupResolutionMethod,
    N'INSERT INTO @GroupResolutionOverride (SourceGroupGuid, SourceGroupName, TargetGroupID, TargetGroupGuid, TargetGroupName, Reason) VALUES ('
        + COALESCE(N'CONVERT(uniqueidentifier,N''' + CONVERT(nvarchar(36), SourceGroupGuid) + N''')', N'NULL')
        + N', '
        + COALESCE(N'N''' + REPLACE(SourceGroupName, N'''', N'''''') + N'''', N'NULL')
        + N', NULL, NULL, N''<DEV group name here>'', N''Approved workflow notification group mapping'');' AS SuggestedOverrideTemplate
FROM #ResolvedWorkflowNotificationGroups
WHERE WorkflowStatusNotificationGroupID <> -1
  AND TargetGroupID IS NULL
ORDER BY
    SourceGroupName,
    WorkflowID,
    WorkflowStatusNotificationGroupID;

SELECT
    grp.ID AS CandidateTargetGroupID,
    grp.Guid AS CandidateTargetGroupGuid,
    grp.Name AS CandidateTargetGroupName,
    grp.RowStatus AS CandidateTargetGroupRowStatus
FROM SCore.Groups AS grp
WHERE grp.RowStatus NOT IN (0,254)
ORDER BY
    grp.Name,
    grp.ID;
